declare const CombatState: CombatState;
declare const Player: Player;
declare const Render: Render;
declare const World: World;
declare const Entity: Entity;
declare const Fs: Fs;
declare const Audio: Audio;
declare const Pvp: Pvp;
declare const Packets: Packets;
declare const Mod: Mod;
declare const Network: Network;
declare const Ws: Ws;
declare const JsonRpc: JsonRpc;
declare const Hud: Hud;
declare const Ui: Ui;
declare const Perf: Perf;
declare const Input: Input;
declare const Cosmetic: Cosmetic;
declare const Animator: Animator;
declare const Intent: Intent;
declare const Shader: Shader;
declare const Package: Package;
declare const Record: Record;
declare const Replay: Replay;
declare const Radial: Radial;
declare const Crystal: Crystal;
declare const Voice: Voice;
declare const ReplayMod: ReplayMod;
